exercises.starter_code:
#include <stdio.h>

int main(void) {
    const char *text = "Hello, World!";
    // strstr, replace, strtok
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
#include <string.h>
    const char *text = "Hello, World!";
    printf("Contains: %s\n", strstr(text, "Hello") ? "true" : "false");
    char buf[32];
    strcpy(buf, text);
    char *w = strstr(buf, "World");
    if (w) { w[0]='G'; w[1]='o'; w[2]='!'; w[3]='\0'; }
    printf("Replaced: %s\n", buf);
    char ab[] = "a,b,c";
    char *tok = strtok(ab, ",");
    printf("First: %s\n", tok);
    return 0;
}

